'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modules = [
 {id:'admissions',name:'Admisiones',icon:'↗',category:'gestion',title:'Una bienvenida bien organizada.',description:'Acompaña al aspirante desde su primera solicitud hasta formar parte de tu comunidad.',features:['Preinscripción en línea y consulta de estatus','Inscripciones y reinscripciones','Seguimiento de solicitudes de ingreso'],benefit:'El comienzo de una trayectoria, con información organizada.'},
 {id:'students',name:'Alumnos y tutores',icon:'◎',category:'gestion',title:'Cada estudiante, con su contexto.',description:'Reúne la información de alumnos y padres o tutores para dar seguimiento a tu comunidad.',features:['Expediente y matrícula del estudiante','Registro de padres y tutores','Relación del estudiante con su grupo'],benefit:'Datos que acompañan al alumno durante su vida escolar.'},
 {id:'groups',name:'Grupos y materias',icon:'▦',category:'academico',title:'La estructura de tu escuela, clara.',description:'Organiza programas, niveles, materias y grupos con sus docentes y estudiantes.',features:['Programas y niveles educativos','Materias y asignaciones de docentes','Grupos por periodo escolar'],benefit:'Cada clase encuentra su lugar.'},
 {id:'schedules',name:'Horarios',icon:'◷',category:'academico',title:'Un lugar para cada clase.',description:'Consulta horarios de grupo y considera la disponibilidad de tus profesores.',features:['Calendario semanal de clases','Disponibilidad horaria del docente','Consulta del horario desde el portal del alumno'],benefit:'Una semana organizada para enseñar y aprender.'},
 {id:'grades',name:'Calificaciones',icon:'9',category:'academico',title:'El avance académico, visible.',description:'Conecta la captura docente con los resultados que consulta cada estudiante.',features:['Captura por materia, criterios y parcial','Boletas y actas de calificaciones','Kardex e historial académico'],benefit:'De la evaluación al seguimiento del aprendizaje.'},
 {id:'attendance',name:'Asistencias',icon:'✓',category:'academico',title:'Cada clase también cuenta.',description:'Registra la asistencia por sesión y consulta el recorrido de cada estudiante.',features:['Presencias, faltas, retardos y justificaciones','Registros por grupo y sesión','Consulta individual en el portal del alumno'],benefit:'Más contexto para acompañar la participación.'},
 {id:'payments',name:'Pagos escolares',icon:'$',category:'gestion',title:'Las cuentas, en su lugar.',description:'Administra colegiaturas y otros conceptos con seguimiento de órdenes y comprobantes.',features:['Conceptos, planes y órdenes de pago','Carga y validación de comprobantes','Consulta de pagos y saldos pendientes'],benefit:'Seguimiento administrativo con información centralizada.'},
 {id:'classroom',name:'Aula virtual',icon:'▤',category:'academico',title:'El aprendizaje continúa aquí.',description:'Un espacio por materia, con una experiencia tipo Classroom para organizar el trabajo de clase.',features:['Actividades, materiales y entregas','Evaluaciones y revisión de resultados','Foros, novedades y sesiones de clase'],benefit:'Profesores y alumnos, conectados con su aprendizaje.'},
 {id:'messages',name:'Mensajería',icon:'☷',category:'comunidad',title:'Una comunidad que se comunica.',description:'Mantén las conversaciones escolares dentro de la plataforma.',features:['Conversaciones entre profesores y alumnos','Mensajes por grupo y archivos adjuntos','Asistencia de IA para redactar desde administración'],benefit:'El contexto de la conversación permanece en la escuela.'},
 {id:'credentials',name:'Credenciales QR',icon:'▧',category:'comunidad',title:'La identidad también es digital.',description:'Credenciales para estudiantes y docentes, vinculadas con tu institución.',features:['Credenciales digitales por persona','Verificación mediante código QR','Consulta desde el portal y formato de credencial'],benefit:'Una identificación vinculada a tu comunidad.'},
 {id:'portals',name:'Portales',icon:'◫',category:'comunidad',title:'Cada persona, su propio espacio.',description:'Alumnos y profesores acceden a las herramientas que les corresponden.',features:['Alumno: materias, notas, asistencia y pagos','Docente: grupos, disponibilidad y calificaciones','Acceso al aula, mensajes y credencial'],benefit:'Experiencias enfocadas en lo que necesita cada perfil.'},
 {id:'institution',name:'Tu institución',icon:'⌂',category:'gestion',title:'Tu escuela conserva su identidad.',description:'Configura la información de tu institución y la estructura que hace única a tu comunidad.',features:['Información y programas institucionales','Identidad visual, logo y colores','Accesos y permisos según el perfil'],benefit:'La plataforma al servicio de tu forma de trabajar.'}
];
let selectedModule='classroom',filter='all';
function renderModules(){
 const visible=modules.filter(m=>filter==='all'||m.category===filter);
 if(!visible.some(m=>m.id===selectedModule))selectedModule=visible[0].id;
 $('module-grid').innerHTML=visible.map(m=>`<button class="module-item ${m.id===selectedModule?'selected':''}" data-module="${m.id}" aria-pressed="${m.id===selectedModule}"><span class="module-icon" aria-hidden="true">${m.icon}</span><span>${m.name}</span></button>`).join('');
 const m=modules.find(m=>m.id===selectedModule);
 $('module-detail').innerHTML=`<span class="detail-icon" aria-hidden="true">${m.icon}</span><h3>${m.title}</h3><p>${m.description}</p><ul class="detail-list">${m.features.map(x=>`<li>${x}</li>`).join('')}</ul><div class="detail-footer">${m.benefit}</div>`;
}
document.querySelector('.filters').addEventListener('click',event=>{const b=event.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});renderModules();});
$('module-grid').addEventListener('click',event=>{const b=event.target.closest('[data-module]');if(!b)return;selectedModule=b.dataset.module;renderModules();document.querySelector(`[data-module="${selectedModule}"]`).focus({preventScroll:true});});
const aiExamples={
 grades:{question:'¿Cuál es el promedio por materia del grupo 2A?',answer:'En este ejemplo, Comunicación tiene el promedio más alto. Este es el resumen del grupo:',body:`<div class="answer-chart" aria-label="Promedios de ejemplo: Matemáticas 8.2, Comunicación 9.1, Ciencias 8.7, Historia 8.9">${[['Matemáticas',8.2],['Comunicación',9.1],['Ciencias',8.7],['Historia',8.9]].map(([name,n])=>`<div><span>${name}</span><i aria-hidden="true"><b style="--value:${n*10}%"></b></i><strong>${n.toFixed(1)}</strong></div>`).join('')}</div>`},
 attendance:{question:'Muéstrame la asistencia del grupo 2A.',answer:'El registro de ejemplo contiene 100 asistencias: 90 presencias, 6 faltas, 3 retardos y 1 justificación.',body:'<div class="ai-result"><strong>94%</strong><small>Índice de asistencia: incluye presencias, retardos y justificaciones.</small></div>'},
 payments:{question:'¿Cuánto hay pendiente de pago este mes?',answer:'En los datos de ejemplo hay 8 órdenes pendientes. Puedes consultar el detalle para dar seguimiento.',body:'<div class="ai-result"><strong>$12,000 MXN</strong><small>8 órdenes de ejemplo de $1,500 cada una.</small></div>'},
 message:{question:'Ayúdame a redactar un aviso sobre la reunión escolar.',answer:'Aquí tienes un borrador para revisar antes de enviarlo:',body:'<div class="ai-result">Estimada comunidad: les invitamos a nuestra próxima reunión escolar. Compartiremos el avance del periodo y los siguientes pasos. Por favor, consulten la fecha y el horario confirmados por la institución. ¡Gracias por acompañar el aprendizaje!</div>'}
};
function renderAI(id){const item=aiExamples[id];$('ai-response').innerHTML=`<div class="user-bubble">${item.question}</div><div class="ai-answer"><span class="answer-label">✦ NENOVA IA</span><p>${item.answer}</p>${item.body}</div>`;document.querySelectorAll('[data-prompt]').forEach(b=>{b.classList.toggle('active',b.dataset.prompt===id);b.setAttribute('aria-pressed',String(b.dataset.prompt===id));});}
document.querySelector('.ai-prompts').addEventListener('click',e=>{const b=e.target.closest('[data-prompt]');if(b)renderAI(b.dataset.prompt);});
const people=['Alex López','Daniela Pérez','Diego Martínez'];
let role='director',teacherView='attendance',studentView='grades';
let state;
function resetState(){state={approved:false,attendance:['present','present','late'],savedAttendance:['present','present','late'],grade:8.7,taskSubmitted:false,fileName:''};}
const roleCopy={
 director:{label:'DIRECCIÓN Y ADMINISTRACIÓN',title:'La visión completa.<br>Las decisiones en tus manos.',text:'Organiza la operación escolar y consulta la información que necesitas para dar seguimiento.',steps:['Explora el resumen académico y administrativo.','Valida un comprobante de ejemplo.','Consulta la demostración del asistente IA.']},
 teacher:{label:'PORTAL DOCENTE',title:'Más espacio<br>para enseñar.',text:'Tus grupos, asistencias, calificaciones y trabajo de clase, desde un mismo espacio.',steps:['Registra la asistencia de tu grupo.','Captura una calificación de ejemplo.','Organiza actividades y revisa entregas.']},
 student:{label:'PORTAL DEL ALUMNO',title:'Tu vida escolar.<br>Siempre a la mano.',text:'Consulta tu avance, encuentra tus actividades y mantente cerca de tu comunidad.',steps:['Consulta tus calificaciones y asistencia.','Explora una actividad y simula su entrega.','Sigue tus pagos y el trabajo de tus materias.']}
};
const pill=(text,pending=false)=>`<span class="status-pill ${pending?'pending':''}">${text}</span>`;
function renderRole(focus=false){
 const c=roleCopy[role];$('role-description').innerHTML=`<span class="role-kicker">${c.label}</span><h3>${c.title}</h3><p>${c.text}</p><ol>${c.steps.map(s=>`<li>${s}</li>`).join('')}</ol>`;
 document.querySelectorAll('[data-role]').forEach(b=>{const active=b.dataset.role===role;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});
 $('role-panel').setAttribute('aria-labelledby','tab-'+role);$('demo-status').textContent='';
 let html='';
 if(role==='director'){
 html=`<div class="screen-top"><div><h4>Así va tu escuela</h4><small>Resumen ilustrativo · Periodo actual</small></div>${pill('Dirección')}</div><div class="screen-metrics"><div><small>Alumnos</small><strong>240</strong><span>En 12 grupos</span></div><div><small>Asistencia</small><strong>94%</strong><span>Registro de ejemplo</span></div><div><small>Por validar</small><strong>${state.approved?'0':'1'}</strong><span>Comprobante de pago</span></div></div><table class="demo-table"><thead><tr><th>SEGUIMIENTO DE PAGOS</th><th>ESTADO</th><th>ACCIÓN</th></tr></thead><tbody><tr><td>Alex López<small class="table-small">Colegiatura · $1,500 MXN</small></td><td>${pill(state.approved?'Validado':'En revisión',!state.approved)}</td><td><button data-demo="approve" ${state.approved?'disabled':''}>${state.approved?'Validado ✓':'Validar ejemplo'}</button></td></tr></tbody></table><a class="demo-action inline-action" href="#ia">Pregúntale al asistente IA ↗</a>`;
 }else if(role==='teacher'){
 html=`<div class="screen-top"><div><h4>Matemáticas II</h4><small>Grupo 2A · Profesora Mariana</small></div>${pill('Portal docente')}</div><div class="demo-nav" aria-label="Herramientas del docente">${[['attendance','Asistencia'],['grades','Calificaciones'],['tasks','Trabajo de clase']].map(([id,label])=>`<button data-teacher="${id}" class="${teacherView===id?'active':''}" aria-pressed="${teacherView===id}">${label}</button>`).join('')}</div>`;
 if(teacherView==='attendance')html+=`<table class="demo-table"><thead><tr><th>ALUMNO</th><th>ASISTENCIA</th></tr></thead><tbody>${people.map((n,i)=>`<tr><td>${n}</td><td><select data-attendance="${i}" aria-label="Asistencia de ${n}">${[['present','Presente'],['absent','Falta'],['late','Retardo'],['justified','Justificada']].map(([v,l])=>`<option value="${v}" ${state.attendance[i]===v?'selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table><button class="demo-action" data-demo="save-attendance">Guardar lista de ejemplo</button>`;
 if(teacherView==='grades')html+=`<form id="grade-form"><div class="assignment"><h5>Captura del primer parcial</h5><p>Alex López · Matemáticas II</p><label for="demo-grade">Calificación de ejemplo (0 a 10)</label><input id="demo-grade" name="grade" type="number" min="0" max="10" step="0.1" value="${state.grade}" required><button class="demo-action" type="submit">Publicar nota de ejemplo</button></div></form>`;
 if(teacherView==='tasks')html+=`<article class="assignment">${pill(state.taskSubmitted?'1 entrega':'Actividad abierta')}<h5>Resolución de ecuaciones</h5><p>Resuelve los ejercicios y explica tu procedimiento. El alumno puede simular una entrega desde su perfil.</p><div class="task-meta"><span>Grupo 2A</span><span>Actividad de ejemplo</span></div>${state.taskSubmitted?`<p class="file-result">Entrega de Alex: ${esc(state.fileName||'ejercicios-ejemplo.pdf')}</p>`:''}</article>`;
 }else{
 html=`<div class="screen-top"><div><h4>Hola, Alex</h4><small>Tu portal escolar · Grupo 2A</small></div>${pill('Alumno')}</div><div class="demo-nav" aria-label="Secciones del alumno">${[['grades','Calificaciones'],['attendance','Asistencias'],['tasks','Mi aula'],['payments','Pagos']].map(([id,label])=>`<button data-student="${id}" class="${studentView===id?'active':''}" aria-pressed="${studentView===id}">${label}</button>`).join('')}</div>`;
 if(studentView==='grades')html+=`<div class="score-mini"><strong>${state.grade.toFixed(1)}</strong><div>Matemáticas II<small>Primer parcial · Nota de ejemplo publicada</small></div></div><p class="screen-hint">Prueba cambiar esta nota desde el perfil de profesor.</p>`;
 if(studentView==='attendance')html+=`<table class="demo-table"><thead><tr><th>MATERIA</th><th>SESIÓN</th><th>ESTADO</th></tr></thead><tbody><tr><td>Matemáticas II</td><td>Ejemplo actual</td><td>${pill({present:'Presente',absent:'Falta',late:'Retardo',justified:'Justificada'}[state.savedAttendance[0]],state.savedAttendance[0]==='absent')}</td></tr><tr><td>Comunicación</td><td>Ejemplo anterior</td><td>${pill('Presente')}</td></tr></tbody></table><p class="screen-hint">El registro de Matemáticas refleja lo guardado en la demo del profesor.</p>`;
 if(studentView==='tasks')html+=`<article class="assignment">${pill(state.taskSubmitted?'Entregada':'Pendiente',!state.taskSubmitted)}<h5>Resolución de ecuaciones</h5><p>Resuelve los ejercicios y explica tu procedimiento.</p>${state.taskSubmitted?`<p class="file-result">${esc(state.fileName||'ejercicios-ejemplo.pdf')} · Por revisar</p>`:`<label for="demo-file">Archivo opcional para la demostración</label><input type="file" id="demo-file" accept=".pdf,.png,.jpg,.jpeg"><button class="demo-action" data-demo="submit-task">Simular entrega</button>`}</article><p class="screen-hint">No se suben archivos. Solo se muestra su nombre durante esta visita.</p>`;
 if(studentView==='payments')html+=`<article class="assignment">${pill(state.approved?'Validado':'En revisión',!state.approved)}<h5>Colegiatura · $1,500 MXN</h5><p>${state.approved?'Tu comprobante de ejemplo fue validado por administración.':'Hay un comprobante de ejemplo en revisión por administración.'}</p></article><p class="screen-hint">Prueba validar este comprobante desde el perfil de dirección.</p>`;
 }
 $('role-screen').innerHTML=`<div class="screen-content">${html}</div>`;
 if(focus)document.querySelector(`[data-role="${role}"]`).focus({preventScroll:true});
}
document.querySelector('.role-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-role]');if(!b)return;role=b.dataset.role;renderRole();});
document.querySelector('.role-tabs').addEventListener('keydown',e=>{const order=['director','teacher','student'];if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=order.indexOf(role);role=e.key==='Home'?order[0]:e.key==='End'?order[2]:order[(i+(e.key==='ArrowRight'?1:2))%3];renderRole(true);});
$('role-screen').addEventListener('change',e=>{if(e.target.dataset.attendance!==undefined)state.attendance[Number(e.target.dataset.attendance)]=e.target.value;if(e.target.id==='demo-file')state.fileName=e.target.files[0]?.name||'';});
$('role-screen').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.teacher){teacherView=b.dataset.teacher;renderRole();}if(b.dataset.student){studentView=b.dataset.student;renderRole();}if(b.dataset.demo==='approve'){state.approved=true;renderRole();$('demo-status').textContent='Comprobante de ejemplo validado. Consulta el cambio en Alumno → Pagos.';}if(b.dataset.demo==='save-attendance'){state.savedAttendance=[...state.attendance];$('demo-status').textContent='Lista de ejemplo guardada. Consulta el registro de Alex en Alumnos → Asistencias.';}if(b.dataset.demo==='submit-task'){state.taskSubmitted=true;renderRole();$('demo-status').textContent='Entrega simulada. El profesor ya puede ver el registro en Trabajo de clase.';}});
$('role-screen').addEventListener('submit',e=>{if(e.target.id!=='grade-form')return;e.preventDefault();const n=Number(new FormData(e.target).get('grade'));if(!Number.isFinite(n)||n<0||n>10)return;state.grade=n;renderRole();$('demo-status').textContent='Nota publicada en la demo. Cambia a Alumnos → Calificaciones para verla.';});
$('reset-demo').addEventListener('click',()=>{resetState();renderRole();$('demo-status').textContent='Datos de demostración restablecidos.';});
const printModules=document.createElement('div');printModules.className='print-modules';printModules.innerHTML=modules.map(m=>`<article><h3>${m.name}</h3><p>${m.features.join(' · ')}.</p></article>`).join('');document.querySelector('.module-explorer').appendChild(printModules);
const printRoles=document.createElement('div');printRoles.className='print-role-summary';printRoles.innerHTML='<strong>Dirección:</strong> administración, seguimiento de pagos y consulta con IA.<br><strong>Profesores:</strong> grupos, asistencia, captura de notas y trabajo de clase.<br><strong>Alumnos:</strong> materias, calificaciones, asistencia, pagos y entregas.';document.querySelector('.role-layout').after(printRoles);
$('print-brochure').addEventListener('click',()=>window.print());
resetState();renderModules();renderAI('grades');renderRole();
